mapper.select:
select u1.U_Name as smrUserName, u2.U_Name as smSendUserName, sm.Sm_Title as smTitle, sm.Sm_Type as smType, sm.Sm_Content as smContent, sm.Sm_Send_User as smSendUser, sm.t_code as tCode, sm.entity_id as entityId, mn.* from Sys_Message_Receive mn left join SYS_User u1 on u1.U_Id=mn.Smr_User left join Sys_Message sm on sm.id=mn.Sm_Id left join SYS_User u2 on u2.U_Id=sm.Sm_Send_User
and mn.Smr_Send_Status=#{params.smrSendStatus}
and mn.Smr_Read=#{params.smrRead}
and mn.Sm_Id=#{params.smId}
and mn.Smr_User=#{params.smrUser}
and INSTR(u1.U_Name,#{params.smrUserName})
and INSTR(sm.Sm_Title,#{params.smTitle})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by sm.Create_Time DESC
